mapper.select:

WHERE P.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
  AND P.ACTIVITY = 1
ORDER BY P.COURSE_NAME_CODE, P.PERIOD_TIME

SELECT TO_CHAR(MAX(TO_NUMBER(PERIOD_TIME)))
  FROM EDU_PLAN_MANAGER
 WHERE CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND ACTIVITY <> 0
   AND COURSE_NUMBER = #{courseNumber, jdbcType=VARCHAR}

SELECT H.PERSON_ID, H.EMPID, H.LOCAL_NAME, H.DEPTNO FROM HR_EMPLOYEE H WHERE H.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND H.EMP_OFFICE = '15119' AND H.DEPTNO IN (SELECT D.DEPTNO FROM HR_DEPARTMENT D START WITH D.DEPTNO IN
#{deptNo, jdbcType=VARCHAR}
CONNECT BY PRIOR D.DEPTNO = D.PARENT_DEPT_NO) ORDER BY H.EMPID

mapper.update:
UPDATE EDU_BASIC_INFORMATION
   SET IMPLE_START_DATE = TO_DATE(#{planStartdate, jdbcType=VARCHAR}, 'DD/MM/YYYY'),
       IMPLE_END_DATE = TO_DATE(#{planEnddate, jdbcType=VARCHAR}, 'DD/MM/YYYY'),
       TRAIN_FORM_CODE = #{trainFormCode, jdbcType=VARCHAR},
       TRAIN_ADDRESS = #{trainAddress, jdbcType=VARCHAR}
 WHERE PLAN_NO = #{planNo, jdbcType=VARCHAR}

UPDATE EDU_PLAN_MANAGER
   SET ACTIVITY = 0,
       UPDATE_DATE = SYSDATE,
       UPDATED_BY = #{adminID, jdbcType=VARCHAR},
       UPDATED_IP = #{adminIP, jdbcType=VARCHAR}
 WHERE PLAN_NO = #{planNo, jdbcType=VARCHAR}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

mapper.delete:
DELETE FROM EDU_TRAIN_SYLLABUS
 WHERE SYLL_NO = #{syllNo, jdbcType=NUMERIC}
   AND PLAN_NO = #{planNo, jdbcType=NUMERIC}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
